cat > /tmp/validate.awk <<'EOF'
{
  line = $0
  sub(/<!--.*-->/, "", line)
  while (match(line, /<[\/]?[a-zA-Z][^>]*>/)) {
    tag = substr(line, RSTART, RLENGTH)
    line = substr(line, RSTART + RLENGTH)
    if (tag ~ /^<\//) close++
    else if (tag ~ /\/>$/) self++
    else open++
  }
}
END {
  print "open=" open, "close=" close, "self-closing=" self
  print (open == close) ? "BALANCED: YES" : "BALANCED: NO"
}
EOF
awk -f /tmp/validate.awk /work/SystemContext.svg

